import 'dart:async'; import 'package:adhan/adhan.dart'; import 'package:flutter/material.dart'; import '../services/prayer_times_service.dart';
class PrayerTimesCard extends StatefulWidget { const PrayerTimesCard({super.key}); @override State<PrayerTimesCard> createState()=>_PrayerTimesCardState(); }
class _PrayerTimesCardState extends State<PrayerTimesCard>{ PrayerTimes? prayerTimes; Timer? timer; bool isLoading=true; @override void initState(){ super.initState(); load(); timer=Timer.periodic(const Duration(seconds:1),(_){ if(mounted&&prayerTimes!=null) setState((){});}); } @override void dispose(){ timer?.cancel(); super.dispose(); } Future<void> load() async { final r=await PrayerTimesService.getPrayerTimes(); if(!mounted) return; setState((){prayerTimes=r; isLoading=false;}); }
@override Widget build(BuildContext context){ if(isLoading) return const Card(child:Padding(padding:EdgeInsets.all(20),child:Center(child:CircularProgressIndicator()))); final t=prayerTimes; if(t==null) return Card(child:ListTile(leading:const Icon(Icons.location_off,color:Colors.orange),title:const Text('مواقيت الصلاة غير متاحة'),subtitle:const Text('فعّل الموقع ثم أعد المحاولة'),trailing:IconButton(icon:const Icon(Icons.refresh),onPressed:(){setState(()=>isLoading=true); load();}))); final next=PrayerTimesService.getNextPrayer(t); return Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Row(children:[Icon(Icons.mosque,color:Colors.green),SizedBox(width:8),Text('مواقيت اليوم',style:TextStyle(fontWeight:FontWeight.bold,fontSize:18))]), if(next!=null)...[const SizedBox(height:12),Container(width:double.infinity,padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:Theme.of(context).colorScheme.primaryContainer,borderRadius:BorderRadius.circular(16)),child:Column(children:[Text('الصلاة القادمة: ${next.name}',style:const TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:6),Text(PrayerTimesService.formatDuration(next.remaining),style:const TextStyle(fontSize:24,fontWeight:FontWeight.bold))]))], const SizedBox(height:15),Wrap(spacing:18,runSpacing:12,children:[_tile('الفجر',t.fajr),_tile('الظهر',t.dhuhr),_tile('العصر',t.asr),_tile('المغرب',t.maghrib),_tile('العشاء',t.isha)])]))); } Widget _tile(String title, DateTime time)=>Column(children:[Text(title,style:const TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:4),Text(PrayerTimesService.formatTime(time))]); }
